public function makeForUnix(array $env, PhpExtensionPackage $package, PackageBuilder $builder): void
{
    $makeArgs = implode(' ', $package->re2cMakeVars());
    // phpize links modules with <EXT>_SHARED_LIBADD, not the configure LIBS env.
    // Carry the resolved static dependency closure onto that final link without
    // embedding libphp. Group archives for transitive/cyclic dependencies and
    // include the toolchain's unwind/C++ runtime even for extensions like opcache.
    $linkConfig = (new SPCConfigUtil(['no_php' => true, 'libs_only_deps' => true]))
        ->configForResolvedBuild([$package->getName()], $package->getInstaller());
    $linkLibs = $linkConfig['libs'];
    if (PHP_OS_FAMILY !== 'Darwin') {
        $linkLibs = clean_spaces("-Wl,--start-group {$linkLibs} -Wl,--end-group");
    }
    $sharedLibadd = strtoupper($package->getExtensionName()) . '_SHARED_LIBADD';
    file_put_contents($package->getSourceRoot() . '/Makefile', "\n{$sharedLibadd} += {$linkLibs}\n", FILE_APPEND);
    shell()->cd($package->getSourceRoot())
        ->setEnv($env)
        ->exec('make clean')
        ->exec("make -j{$builder->concurrency} {$makeArgs}")
        ->exec("make install {$makeArgs}")
        // distclean after install: phpize build residues (.lo/.libs/config.status) would
        // poison a later static in-tree build sharing this source dir (php-src's make
        // clean uses find, which does not follow the ext symlink)
        ->exec('make distclean');
}
